mapper.select:
select gc.shop_id,gc.shop_name from ${database.prefix.order}hou_goods_jingdong_dropshipping gjd left join ${database.prefix.goods}hou_goods_common gc on gjd.common_id = gc.common_id where gc.common_name is not null and gjd.spu_id = #{param.supplyCommonId}
and gc.shop_name like CONCAT('%',#{param.shopName},'%')
group by gc.shop_id
